SELECT 'gongkao', '关键句理解', 'kp-xingce-language-reading-word-sentence-key-sentence', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "关键句理解"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "联系上下文，解释这句话在文中的特定义。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、解题步骤"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这句话一定起着承上启下的作用。往前看一句，往后看一句，同义替换即为答案。"}]}]}$$ AS jsonb), NULL, '关键句理解的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "关键句理解"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_word_sentence_key_sentence", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
